  Bu = `โปรดใช้ปุ่มทางขวามือเพื่อส่งเว็บเพจของคุณไปรับการตรวจสอบล่วงหน้าอย่างน้อย 7 วันก่อนวันเผยแพร่ที่คุณต้องการ ทั้งนี้เพื่อให้แน่ใจว่ามีเวลาเพียงพอที่จะตรวจสอบ/อนุมัติ และดำเนินการเปลี่ยนแปลงที่จำเป็น`,
  Vu = `หากมีการเปลี่ยนแปลงใด ๆ ที่จำเป็นต่อหน้าเว็บของคุณ ทีมงาน Steam จะติดต่อคุณผ่านทางตั๋วฝ่ายสนับสนุน Steamworks คุณสามารถดูตั๋วฝ่ายสนับสนุน Steamworks และกรอกความคิดเห็นเพิ่มได้หากจำเป็น โดยคลิกปุ่มทางด้านขวา`,
  Hu = `การทำเครื่องหมายระบุว่าหน้านี้ได้รับการอนุมัติแล้วจะทำให้พันธมิตรสามารถประกาศและเริ่มต้นลดราคาได้`,
  Uu = `ขอให้ตรวจสอบ...`,
  Wu = `ขอรับการตรวจสอบ`,
  Gu = `สร้างตั๋วเพื่อขอให้ตรวจสอบการอนุมัติให้เผยแพร่หน้าการลดราคา โปรดดำเนินการดังกล่าวนี้เมื่อหน้าการลดราคาของคุณมีอาร์ตเวิร์กขั้นสุดท้ายและเกมทั้งหมดที่คุณต้องการนำเสนอแล้ว`,
  Ku = `คำขอนี้จะสร้างตั๋วฝ่ายสนับสนุน Steamworks เพื่อขอให้ Valve ตรวจสอบหน้าการลดราคาของคุณ โดยควรดำเนินการดังกล่าวเฉพาะเมื่ออาร์ตเวิร์กและข้อความของคุณเสร็จเรียบร้อย และรายชื่อเกมเสร็จสมบูรณ์แล้วเท่านั้น`,
  qu = `โปรดตรวจสอบให้แน่ใจว่าชื่อกิจกรรมและวัตถุประสงค์ของคุณมีคำอธิบายที่ชัดเจนใกล้กับด้านบนสุดของหน้า ในกรณีที่เป็นกล่องแสดงผลงาน คุณอาจจำเป็นต้องมีส่วนข้อความที่ด้านบนสุดของหน้าเว็บของคุณ เพื่ออธิบายว่ากล่องแสดงผลงานของคุณคืออะไรและทำงานอย่างไร`,
  Ju = `หน้าการลดราคาจะถูกล็อกเมื่อได้รับการตรวจสอบแล้ว หากคุณต้องการเปลี่ยนแปลงหลังจากการตรวจสอบหรือเมื่อกิจกรรมเริ่มขึ้น โปรดเขียนในความคิดเห็นว่าการเปลี่ยนแปลงเหล่านั้นเกี่ยวข้องกับอะไรบ้าง และทำไมจึงไม่สามารถทำได้ก่อนการตรวจสอบ`,
  Yu = `เลือกได้:  ข้อมูลที่คุณต้องการรวมไว้เพื่อให้ผู้ตรวจสอบได้พิจารณา`,
  Xu = `เลือกพันธมิตรที่สมาชิกสามารถเข้าถึงตั๋วคำขอได้เช่นกัน`,
  Zu = `เลือกได้:  หากเลือกไว้ สมาชิกคนอื่น ๆ ของพันธมิตรจะสามารถเข้าถึงและตอบกลับตั๋วได้ ค่าเริ่มต้นจะกำหนดให้คุณเท่านั้นที่สามารถอ่าน อัปเดต และตอบกลับตั๋วที่สร้างขึ้นได้`,
