  $u = `ไม่สามารถสร้างตั๋วใหม่ได้ เพราะมีตั๋วประเภทนี้อยู่แล้ว โปรดตรวจสอบหน้าการลดราคาอื่นของคุณให้เสร็จสิ้นก่อนที่จะส่งหน้านี้ หรืออัปเดตตั๋วที่มีอยู่เพื่อให้รวมการตรวจสอบของหน้านี้ไว้ด้วย`,
