  qV = `บางวัน ต้องเกมแบบเน้นคำบรรยายเท่านั้นถึงจะโดนใจคุณ และเกมนี้เต็มไปด้วยบทบรรยายที่จับจิตจับใจเหมือนละครทีวีทั่วไป และผ่านการปรุงแต่งมาอย่างดีไม่ผิดกับบทภาพยนตร์โทรทัศน์ชั้นเยี่ยม ไชโย - เกมนี้ทำให้เรารู้สึกรู้สาได้อีก!`,
  JV = `เกมนี้เหมือนไอศกรีมในวันอากาศร้อน เนื้อนุ่มลิ้น ชิมแล้วสบายใจ ละลายความเครียดจนเกลี้ยง เกมนี้จะช่วยให้คุณมีจิตสุขใจสงบ`,
