  XV = `คุณมีสิทธิ์เสนอชื่อเข้าชิงรางวัลในแต่ละหมวดได้เพียงเกมเดียวเท่านั้น และคุณได้เสนอชื่อเกม %1$s ในหมวดนี้ไปแล้ว คุณต้องการที่จะเสนอชื่อเกม %2$s แทนใช่หรือไม่?`,
  ZV = `โหวต`,
  QV = `โหวตแล้ว`,
