  eH = `เปลี่ยนการโหวตของคุณ?`,
  tH = `คุณมีสิทธิ์โหวตในแต่ละหมวดได้เพียงเกมเดียวเท่านั้น และคุณได้โหวตให้เกม %1$s ในหมวดนี้ไปแล้ว คุณต้องการที่จะเปลี่ยนไปโหวตให้ %2$s แทนใช่หรือไม่?`,
  nH = `ดูเหมือนว่าบัญชีของคุณเป็นบัญชีแบบจำกัดสิทธิ์ ดังนั้นคุณต้องซื้อสินค้าบน Steam ครบ 5 ดอลลาร์สหรัฐ จึงจะมีสิทธิ์เข้าร่วมงานรางวัล Steam ได้ ทั้งนี้เพื่อไม่ให้ผิดกฎการเสนอชื่อเกม หากต้องการข้อมูลเพิ่มเติม %1$s`,
  rH = `ดูเหมือนว่าบัญชีของคุณเป็นบัญชีแบบจำกัดสิทธิ์ ดังนั้นคุณต้องซื้อสินค้าบน Steam ครบ 5 ดอลลาร์สหรัฐ จึงจะมีสิทธิ์เข้าร่วมงานรางวัล Steam ได้ ทั้งนี้เพื่อไม่ให้ผิดกฎการโหวต หากต้องการข้อมูลเพิ่มเติม %1$s`,
  iH = `เกมแห่งปี`,
  aH = `เกม VR แห่งปี`,
  oH = `ทำงานด้วยใจรัก`,
  sH = `ดีกว่าถ้ามีเพื่อน`,
  cH = `สไตล์ภาพดีเด่น`,
  lH = `เกมเพลย์สร้างสรรค์ยอดเยี่ยม`,
  uH = `เกมที่คุณเล่นได้ห่วยแตกที่สุด`,
  dH = `เพลงประกอบยอดเยี่ยม`,
