  gH = `เกมนี้วางจำหน่ายได้พักใหญ่แล้ว และทีมงานก็ผ่านพ้นช่วงที่อุ้มลูกน้อยออกอวดชาวบ้านเป็นครั้งแรกมานาน แต่เนื่องจากเป็นพ่อแม่ที่น่ารัก ผู้พัฒนาเหล่านี้จึงดูแลเอาใจใส่ลูกน้อยด้วยดีเสมอมา เกมนี้จึงยังคงมีเนื้อหาใหม่ ๆ มาตลอดเวลาที่วางจำหน่ายหลายปีจนกระทั่งถึงวันนี้`,
  _H = `มีบางเกมที่คุณเล่นคนเดียวแล้วไม่สนุกเอาเสียเลย บางทีคุณอาจต้องมีเพื่อนไว้คอยเฝ้าระวังหลังให้คุณ บางทีคุณอาจต้องมีเพื่อนไว้ให้คุณแอบแทงหลังได้ ไม่ว่าแบบไหนก็ตาม ความสนุกกำลังรอให้คุณรวบรวมสมัครพรรคพวกมาร่วมเล่นเกมนี้ด้วยกัน`,
