  yH = `ผู้ออกแบบเกมนี้ยืนอยู่แถวหน้าของการทดสอบความสร้างสรรค์ โดยนำเสนอมุมมองที่แปลกใหม่และสิ่งที่สร้างความประหลาดใจจนสมองตามไม่ทัน เกมนี้เปี่ยมด้วยความปลื้มปีติ แรงบันดาลใจ และความบันเทิงที่มาพร้อมความใหม่เอี่ยมที่ไม่เคยเล่นมาก่อน`,
  bH = `นี่เป็นเกมที่ให้รางวัลความอึดและไม่เหมาะสำหรับคนใจเสาะ แต่เป็นเกมที่ยากที่สุดที่เราชื่นชอบ`,
  xH = `เพลงดีที่โลกลืมนี้สมควรได้รับการยกย่องว่ามีโน้ตเพลงยอดเยี่ยม จัดเป็นเพลงประกอบที่โดดเด่นที่สุด! `,
  SH = `บางวัน ต้องเกมแบบเน้นคำบรรยายเท่านั้นถึงจะโดนใจคุณ และเกมนี้เต็มไปด้วยบทบรรยายที่จับจิตจับใจเหมือนละครทีวี และผ่านการปรุงแต่งมาอย่างดีไม่ผิดกับบทภาพยนตร์โทรทัศน์ชั้นเยี่ยม ยอดมาก - ที่กระตุ้นความรู้สึกของเราได้อย่างนี้!`,
