  kH = `เกมเพลย์สร้างสรรค์ยอดเยี่ยม`,
  AH = `เกมที่คุณเล่นได้ห่วยแตกที่สุด`,
  jH = `เพลงประกอบยอดเยี่ยม`,
  MH = `เกมเน้นการเล่าเรื่องดีเด่น`,
