  PH = `เกมพกพายอดเยี่ยม`,
  FH = `บางทีอาจเป็นเพราะมีเกมเพลย์ที่ชวนดื่มด่ำ หรือเรื่องราวที่จับจิตจับใจ... ตัวละครที่ปั้นแต่งไว้เป็นอย่างดี การออกแบบที่ไร้ที่ติ หรือโหมดผู้เล่นหลายคนที่เล่นได้ไม่เบื่อ ไม่ว่าด้วยเหตุผลใดก็ตาม เกมที่ชนะรางวัลเกมแห่งปีประจำปีนี้จะก้าวขึ้นแท่นเกมคลาสสิกทันที`,
  IH = `เกม VR แห่งปีไม่ได้ซ่อนตัวอยู่หลังหน้ากากความเป็นจริงตามปกติ แต่ยกระดับความเป็นจริงโดยใช้ประโยชน์จากสื่อ VR และพุ่งทะยานผ่านขอบกั้นโลกเสมือนจริง`,
  LH = `เกมนี้วางจำหน่ายได้พักใหญ่แล้ว และทีมงานก็ผ่านพ้นช่วงที่อุ้มลูกน้อยออกอวดชาวบ้านเป็นครั้งแรกมานาน แต่เนื่องจากเป็นพ่อแม่ที่น่ารัก ผู้พัฒนาเหล่านี้จึงดูแลเอาใจใส่ลูกน้อยด้วยดีเสมอมา เกมนี้จึงยังคงมีเนื้อหาใหม่ ๆ มาตลอดเวลาที่วางจำหน่ายหลายปีจนกระทั่งถึงวันนี้`,
