  zH = `สไตล์ภาพไม่ได้มุ่งหมายให้มีความเที่ยงตรงตามแบบภาพกราฟิกในโลกแห่งความเป็นจริง (แม้ว่าจะเป็นเป้าหมายอันสูงส่งในตัวเองก็ตาม)... แต่แสดงถึงรูปลักษณ์และความรู้สึกอันโดดเด่นที่แทรกซึมไปทั่วทั้งเกม`,
  BH = `ผู้ออกแบบเกมนี้ยืนอยู่แถวหน้าของการทดสอบความสร้างสรรค์ โดยนำเสนอมุมมองที่แปลกใหม่และสิ่งที่สร้างความประหลาดใจจนสมองตามไม่ทัน เกมนี้เปี่ยมด้วยความปลื้มปีติ แรงบันดาลใจ และความบันเทิงที่มาพร้อมความใหม่เอี่ยมที่ไม่เคยเล่นมาก่อน`,
  VH = `นี่เป็นเกมที่ให้รางวัลความอึดและไม่เหมาะสำหรับคนใจเสาะ แต่เป็นเกมที่ยากที่สุดที่เราชื่นชอบ`,
