  UH = `บางวัน ต้องเกมแบบเน้นการเล่าเรื่องราวเท่านั้นถึงจะโดนใจคุณ และเกมนี้เต็มไปด้วยบทบรรยายที่จับจิตจับใจเหมือนละครทีวี และผ่านการปรุงแต่งมาอย่างดีไม่ผิดกับบทภาพยนตร์โทรทัศน์ชั้นเยี่ยม ยอดมาก - ที่กระตุ้นความรู้สึกของเราได้ขนาดนี้!`,
  WH = `เกมนี้เหมือนไอศกรีมในวันอากาศร้อน ทั้งหวาน ทั้งเย็น ละลายความเครียดจนเกลี้ยง เกมนี้จะช่วยให้คุณมีจิตสุขใจสงบ`,
  GH = `เกมนี้สนุกมากจนคุณอยากเอาติดตัวไปด้วยทุกที่ คุณก็เลยทำจริง ๆ! และโชคดีที่สิ่งที่ทำให้คุณเล่นได้สนุกจนไม่อยากเลิกที่บ้าน ยิ่งยอดเยี่ยมขึ้นไปอีกขณะพกพา`,
  KH = `เฉพาะ VR เท่านั้น`,
  qH = `รองรับ VR`,
  JH = `เหลืออีก %1$s กว่าจะมีการสุ่มจับรางวัลครั้งถัดไป!`,
  YH = `เวลาที่เหลือจนกว่าจะมีการสุ่มจับรางวัลครั้งถัดไป`,
  XH = `จับตาดูเพื่อรับโอกาสชนะรางวัล!`,
  ZH = `การสุ่มจับรางวัลอยู่ระหว่างดำเนินการ`,
  QH = `จำนวนของผู้โชคดีได้รับรางวัลที่ผ่านมา!`,
  $H = `ขณะนี้การแจกรางวัลได้สิ้นสุดลงแล้ว ขอขอบคุณที่เข้าร่วมสนุกกับเรา`,
  eU = `ขณะนี้การแจกรางวัลได้สิ้นสุดลงแล้ว โดยมีผู้โชดดีได้รับรางวัล %1$s ขอขอบคุณที่เข้าร่วมสนุกกับเรา`,
  tU = `คลิกเพื่อเรียนรู้เพิ่มเติมเกี่ยวกับรางวัล ผู้ชนะ และกฎกติกา`,
  nU = `หมั่นกลับมาดูของขวัญชิ้นใหม่จากองค์จักรพรรดิได้ทุกวัน!`,
