  fU = `เปิด %1$s`,
  pU = `โปรดใช้เบราว์เซอร์ที่รองรับวิดีโอ HTML เพื่อเปิดซองอั่งเปาของคุณ`,
  mU = `กลับไปยังเทศกาลลดราคา`,
